  R.icon = function (key, cls) {
    const paths = R.ICONS[key];
    if (!paths) return '';
    return '<svg class="ico ' + (cls || '') + '" viewBox="0 0 512 512" aria-hidden="true">' + paths.map(d => '<path d="' + d + '"/>').join('') + '</svg>';
  };
